import * as THREE from'three';import{createToyKit}from'../world/toy-kit.js';import{CLIMB,climbContactFrame}from'./climb-contacts.js';
const ease=t=>{t=Math.max(0,Math.min(1,t));return t*t*(3-2*t)},mix=(a,b,t)=>a+(b-a)*t;
export const PULLUP=Object.freeze({x:-1.8,z:-.8,railY:1.24,halfWidth:.8,rootZ:-.26,baseY:.36,lift:.18,radius:.04});
export const CLIMB_DURATION=1.55+3*CLIMB.cycleSeconds;
export function pullupExerciseFrame(raise=0){const q=Math.max(0,Math.min(1,raise)),y=PULLUP.baseY+PULLUP.lift*q;return{root:{x:PULLUP.x,y,z:PULLUP.rootZ,yaw:Math.PI},hands:{left:[.545,PULLUP.railY-y,.54],right:[.545,PULLUP.railY-y,.54]},footOffsets:{left:[0,0,0],right:[0,0,0]},arm:1,foot:0};}
export function climbExerciseFrame(seconds=0){const t=Math.max(0,Math.min(CLIMB_DURATION,Number.isFinite(seconds)?seconds:0));if(t>=1.55)return{...climbContactFrame(t-1.55),arm:1,foot:1};const support=CLIMB.rungs[0]+CLIMB.footSupportOffset,rootY=t<1.35?.05:mix(.05,support,ease((t-1.35)/.20)),hands={left:[.68,.76-rootY,.54],right:[.68,.76-rootY,.54]},footOffsets={left:[0,0,0],right:[0,0,0]};for(const[side,start]of[['left',.35],['right',.85]]){const u=ease((t-start)/.5);footOffsets[side]=[0,(support-.05)*u+.14*Math.sin(Math.PI*u)-Math.max(0,rootY-.05),.28*u];}return{root:{x:CLIMB.rootX,y:rootY,z:CLIMB.rootZ,yaw:Math.PI},hands,footOffsets,arm:ease(t/.35),foot:1};}
export const SPORTS_EQUIPMENT_OBSTACLES=[{x:-1.8,z:-.8,hx:.85,hz:.04},{x:-2.6,z:-.8,hx:.055,hz:.055},{x:-1,z:-.8,hx:.055,hz:.055},{x:-4.4,z:.9,hx:.96,hz:.9},{x:-4.4,z:1.82,hx:.53,hz:.03}];
export const SPORTS_EQUIPMENT_ACTIVITIES=[{id:'sportsField.pullup',type:'pose',at:{x:-1.8,z:.48},exit:{x:-1.8,z:.48,yaw:0},anchor:{x:-1.8,y:.36,z:-.26,yaw:Math.PI},radius:.72,requiresClearApproach:true,label:'낮은 철봉에 매달리기',kind:'pullup',poseName:'pullup',enterDuration:1.1,duration:6,discoveryId:'school-pullup',leaveLabel:'철봉에서 내려오기',text:'양손으로 낮은 철봉을 잡고 발을 살짝 들어요. 나가기를 누르면 먼저 몸을 낮추고 내려와요.'},{id:'sportsField.climb',type:'pose',at:{x:-4.4,z:2.65},exit:{x:-4.4,z:2.65,yaw:0},anchor:{x:CLIMB.rootX,y:.05,z:CLIMB.rootZ,yaw:Math.PI},radius:.70,requiresClearApproach:true,label:'정글짐 사다리 오르기',kind:'climb',poseName:'climb',enterDuration:.6+CLIMB_DURATION,duration:2.6,discoveryId:'school-climb',leaveLabel:'사다리로 내려오기',text:'손과 발을 번갈아 옮겨 정글짐 사다리를 올라요. 위에서 잠깐 둘러본 뒤 같은 발판으로 내려와요.'}];
export function buildSportsEquipment(parent){const kit=createToyKit(parent),bar=new THREE.Group();bar.name='sportsField.pullup';parent.add(bar);for(const x of[-2.6,-1]){kit.cylinder(.05,.05,1.26,'#789e94',x,.64,-.8,bar);kit.sphere(.061,'#e8c777',x,1.29,-.8,1,1,1,bar);}const rail=kit.cylinder(.04,.04,1.70,'#d7b176',-1.8,1.24,-.8,bar);rail.rotation.z=Math.PI/2;kit.box(2.15,.025,1.65,'#bfd1af',-1.8,.025,-.30,.10,bar);
 const gym=new THREE.Group();gym.name='sportsField.climb';parent.add(gym);kit.box(1.80,.10,1.60,'#d8bf89',-4.4,1.00,.9,.04,gym);for(const x of[-5.3,-3.5])for(const z of[.1,1.7]){kit.cylinder(.055,.055,1.79,'#83a9a0',x,.91,z,gym);kit.sphere(.072,'#e3bc72',x,1.83,z,1,1,1,gym);}for(const x of[-5.3,-3.5])for(const y of[.38,.73,1.4,1.75]){const n=kit.cylinder(.025,.025,1.6,'#b9d0b1',x,y,.9,gym);n.rotation.x=Math.PI/2;}for(const y of[.38,.73,1.4,1.75]){const n=kit.cylinder(.025,.025,1.8,'#b9d0b1',-4.4,y,.1,gym);n.rotation.z=Math.PI/2;}
 for(const dx of[-.5,.5])kit.cylinder(.025,.025,1.02,'#d8b580',-4.4+dx,.54,CLIMB.rungZ,gym);for(const y of CLIMB.rungs){const n=kit.cylinder(CLIMB.railRadius,CLIMB.railRadius,1,'#d8b580',-4.4,y,CLIMB.rungZ,gym);n.rotation.z=Math.PI/2;}for(const dx of[-.68,.68]){kit.cylinder(.035,.035,1.70,'#779d93',-4.4+dx,.90,CLIMB.rungZ,gym);kit.sphere(.042,'#e3bc72',-4.4+dx,1.75,CLIMB.rungZ,1,1,1,gym);}return{bar,gym};}
